from decimal import Decimal, ROUND_HALF_UP

def round_money(amount):
    """Round a monetary amount to two decimal places."""
    return Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

def format_money(amount):
    """Format a monetary amount as a string with two decimal places."""
    return f"{round_money(amount):.2f}"

def add_money(*amounts):
    """Add multiple monetary amounts and return the rounded result."""
    return round_money(sum(Decimal(str(amount)) for amount in amounts))
